def rotate_90cw(grid):
    h, w = len(grid), len(grid[0])
    return [[grid[h-1-j][i] for j in range(h)] for i in range(w)]

def rotate_90ccw(grid):
    h, w = len(grid), len(grid[0])
    return [[grid[j][w-1-i] for j in range(h)] for i in range(w)]

def rotate_180(grid):
    return rotate_90cw(rotate_90cw(grid))

def transform(grid):
    h, w = len(grid), len(grid[0])
    result = [[0] * (2*w) for _ in range(2*h)]

    # TL: identity
    for i in range(h):
        for j in range(w):
            result[i][j] = grid[i][j]

    # TR: 90 CW
    for i in range(h):
        for j in range(w):
            result[i][j+w] = rotate_90cw(grid)[i][j]

    # BL: 90 CCW
    for i in range(h):
        for j in range(w):
            result[i+h][j] = rotate_90ccw(grid)[i][j]

    # BR: 180
    for i in range(h):
        for j in range(w):
            result[i+h][j+w] = rotate_180(grid)[i][j]

    return result

